  1	/**
  2	 * Contrato del perfil de límites de recursos de un worker de Podman
  3	 * (ADR-THYROX-007 Regla 2, TASK-THYROX-0615).
  4	 *
  5	 * Cada bandera que este módulo compone ya se midió contra su control en
  6	 * `src/lib/podman_capabilities.sh` (`--pids-limit`, `--memory`, `--cpus`,
  7	 * `--network none`, `--read-only`, montajes `:ro`). Aquí sólo vive el
  8	 * CONTRATO del perfil —su validación y su traducción a argv—, nunca la
  9	 * ejecución: el `PodmanWorkerManager` que crea y lanza contenedores es
 10	 * trabajo futuro, no de este archivo.
 11	 */
 12	
 13	/**
 14	 * `host` existe porque, medido en el contenedor remoto, el proxy de salida
 15	 * escucha en el loopback del anfitrión (`127.0.0.1`) y ni `bridge` ni
 16	 * `slirp4netns` lo alcanzan. Su costo: el trabajo ve TODO servicio del
 17	 * loopback del anfitrión (Redis, Ollama, el proxy local). Por eso nunca es
 18	 * el default y se declara sólo para trabajos sin credencial cuyo único
 19	 * destino de red es el exterior.
 20	 */
 21	export type WorkerNetworkMode = 'none' | 'bridge' | 'host'
 22	export type WorkerMountMode = 'ro' | 'rw'
 23	
 24	export type WorkerResourceMount = {
 25	  source: string
 26	  destination: string
 27	  mode: WorkerMountMode
 28	}
 29	
 30	export type WorkerResourceProfile = {
 31	  cpus: number
 32	  memoryMib: number
 33	  pidsLimit: number
 34	  network: WorkerNetworkMode
 35	  readOnlyRootfs: boolean
 36	  mounts: WorkerResourceMount[]
 37	  /**
 38	   * Variables del proceso del trabajo. Su valor queda en `Config.Env` de
 39	   * `podman inspect` (medido 2026-09-29, `repositoryJobProfile.ts`), así que
 40	   * sólo admite valores públicos: un nombre de credencial se rehúsa.
 41	   */
 42	  environment?: Readonly<Record<string, string>>
 43	  /**
 44	   * Puertos del contenedor publicados en el anfitrión. Sólo en loopback
 45	   * (`127.0.0.1`): un servicio de un worker nunca escucha en la red del
 46	   * anfitrión. Se emiten como `-p 127.0.0.1:<host>:<contenedor>`.
 47	   */
 48	  publishedPorts?: readonly WorkerPublishedPort[]
 49	  /**
 50	   * Dispositivos concedidos, en forma CDI (`nvidia.com/gpu=<uuid>`). Una ruta
 51	   * de `/dev` se rehúsa: el dispositivo lo nombra el grant, no el anfitrión.
 52	   */
 53	  devices?: readonly string[]
 54	}
 55	
 56	export type WorkerPublishedPort = {
 57	  hostAddress: '127.0.0.1'
 58	  hostPort: number
 59	  containerPort: number
 60	}
 61	
 62	const KNOWN_NETWORK_MODES: readonly WorkerNetworkMode[] = ['none', 'bridge', 'host']
 63	const ENVIRONMENT_NAME_PATTERN = /^[A-Za-z_][A-Za-z0-9_]*$/
 64	const CREDENTIAL_NAME_PATTERN = /(TOKEN|SECRET|PASSWORD|PASSWD|KEY|CREDENTIAL)/i
 65	const KNOWN_MOUNT_MODES: readonly WorkerMountMode[] = ['ro', 'rw']
 66	const LOOPBACK_HOST_ADDRESS = '127.0.0.1'
 67	const MIN_PORT = 1
 68	const MAX_PORT = 65_535
 69	/** La red que publica puertos: `none` no tiene a dónde y `host` no lo necesita. */
 70	const PORT_PUBLISHING_NETWORK: WorkerNetworkMode = 'bridge'
 71	/** Nombre CDI de un dispositivo: `<vendor>/<clase>=<nombre>` (`nvidia.com/gpu=<uuid>`). */
 72	const CDI_DEVICE_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*\/[A-Za-z0-9][A-Za-z0-9._-]*=[A-Za-z0-9][A-Za-z0-9._:-]*$/
 73	
 74	/**
 75	 * El perfil más restrictivo medido: sin red, rootfs de sólo lectura, sin
 76	 * montajes declarados. Relajar cualquiera de los tres es explícito en el
 77	 * perfil que se declare — nunca el default silencioso.
 78	 */
 79	export const DEFAULT_WORKER_RESOURCE_PROFILE: WorkerResourceProfile = {
 80	  cpus: 1,
 81	  memoryMib: 1024,
 82	  pidsLimit: 128,
 83	  network: 'none',
 84	  readOnlyRootfs: true,
 85	  mounts: [],
 86	}
 87	
 88	/** Un campo del perfil no pasó su validación; nombra el campo, nunca lo omite en silencio. */
 89	export class InvalidWorkerResourceProfileError extends Error {
 90	  readonly field: string
 91	
 92	  constructor(field: string, message: string) {
 93	    super(message)
 94	    this.name = 'InvalidWorkerResourceProfileError'
 95	    this.field = field
 96	  }
 97	}
 98	
 99	function requirePositiveNumber(field: string, value: number): void {
100	  if (!Number.isFinite(value) || value <= 0) {
101	    throw new InvalidWorkerResourceProfileError(field, `${field} debe ser un número > 0, recibido: ${value}`)
102	  }
103	}
104	
105	function requirePositiveInteger(field: string, value: number): void {
106	  if (!Number.isInteger(value) || value < 1) {
107	    throw new InvalidWorkerResourceProfileError(field, `${field} debe ser un entero >= 1, recibido: ${value}`)
108	  }
109	}
110	
111	function requireKnownNetwork(network: WorkerNetworkMode): void {
112	  if (!KNOWN_NETWORK_MODES.includes(network)) {
113	    throw new InvalidWorkerResourceProfileError('network', `red desconocida: ${network}`)
114	  }
115	}
116	
117	function requireValidMount(mount: WorkerResourceMount, index: number): void {
118	  const field = `mounts[${index}]`
119	  if (!mount.source) {
120	    throw new InvalidWorkerResourceProfileError(`${field}.source`, 'el origen del montaje no puede estar vacío')
121	  }
122	  if (!mount.destination.startsWith('/')) {
123	    throw new InvalidWorkerResourceProfileError(
124	      `${field}.destination`,
125	      `el destino del montaje debe ser una ruta absoluta, recibido: ${mount.destination}`,
126	    )
127	  }
128	  if (!KNOWN_MOUNT_MODES.includes(mount.mode)) {
129	    throw new InvalidWorkerResourceProfileError(`${field}.mode`, `modo de montaje desconocido: ${mount.mode}`)
130	  }
131	}
132	
133	/** Valida el perfil completo; rehúsa en el primer campo inválido, nombrándolo. */
134	export function validateWorkerResourceProfile(profile: WorkerResourceProfile): void {
135	  requirePositiveNumber('cpus', profile.cpus)
136	  requirePositiveNumber('memoryMib', profile.memoryMib)
137	  requirePositiveInteger('pidsLimit', profile.pidsLimit)
138	  requireKnownNetwork(profile.network)
139	  profile.mounts.forEach((mount, index) => requireValidMount(mount, index))
140	  Object.keys(profile.environment ?? {}).forEach(requirePublicEnvironmentName)
141	  requireValidPublishedPorts(profile)
142	  profile.devices?.forEach(requireCdiDevice)
143	}
144	
145	function isValidPort(port: number): boolean {
146	  return Number.isInteger(port) && port >= MIN_PORT && port <= MAX_PORT
147	}
148	
149	function requireValidPublishedPorts(profile: WorkerResourceProfile): void {
150	  const ports = profile.publishedPorts ?? []
151	  if (ports.length > 0 && profile.network !== PORT_PUBLISHING_NETWORK) {
152	    throw new InvalidWorkerResourceProfileError(
153	      'publishedPorts',
154	      `publicar puertos exige red ${PORT_PUBLISHING_NETWORK}, el perfil declara ${profile.network}`,
155	    )
156	  }
157	  ports.forEach(requireValidPublishedPort)
158	}
159	
160	function requireValidPublishedPort(port: WorkerPublishedPort, index: number): void {
161	  const field = `publishedPorts.${index}`
162	  if (port.hostAddress !== LOOPBACK_HOST_ADDRESS) {
163	    throw new InvalidWorkerResourceProfileError(`${field}.hostAddress`, `sólo se publica en ${LOOPBACK_HOST_ADDRESS}, recibido: ${port.hostAddress}`)
164	  }
165	  if (!isValidPort(port.hostPort)) {
166	    throw new InvalidWorkerResourceProfileError(`${field}.hostPort`, `puerto fuera de ${MIN_PORT}–${MAX_PORT}: ${port.hostPort}`)
167	  }
168	  if (!isValidPort(port.containerPort)) {
169	    throw new InvalidWorkerResourceProfileError(`${field}.containerPort`, `puerto fuera de ${MIN_PORT}–${MAX_PORT}: ${port.containerPort}`)
170	  }
171	}
172	
173	function requireCdiDevice(device: string, index: number): void {
174	  if (!CDI_DEVICE_PATTERN.test(device)) {
175	    throw new InvalidWorkerResourceProfileError(`devices.${index}`, `el dispositivo debe ir en forma CDI <vendor>/<clase>=<nombre>, recibido: ${device}`)
176	  }
177	}
178	
179	function requirePublicEnvironmentName(name: string): void {
180	  const field = `environment.${name}`
181	  if (!ENVIRONMENT_NAME_PATTERN.test(name)) {
182	    throw new InvalidWorkerResourceProfileError(field, `nombre de variable inválido: ${name}`)
183	  }
184	  if (CREDENTIAL_NAME_PATTERN.test(name)) {
185	    throw new InvalidWorkerResourceProfileError(field, `${name} nombra una credencial y su valor quedaría en podman inspect`)
186	  }
187	}
188	
189	function cpuLimitArgv(cpus: number): string[] {
190	  return ['--cpus', String(cpus)]
191	}
192	
193	function memoryLimitArgv(memoryMib: number): string[] {
194	  return ['--memory', `${memoryMib}m`]
195	}
196	
197	function pidsLimitArgv(pidsLimit: number): string[] {
198	  return ['--pids-limit', String(pidsLimit)]
199	}
200	
201	function networkArgv(network: WorkerNetworkMode): string[] {
202	  return ['--network', network]
203	}
204	
205	function rootfsArgv(readOnlyRootfs: boolean): string[] {
206	  return readOnlyRootfs ? ['--read-only', '--read-only-tmpfs=false'] : []
207	}
208	
209	function environmentArgv(environment: Readonly<Record<string, string>>): string[] {
210	  return Object.keys(environment).sort().flatMap(name => ['--env', `${name}=${environment[name]}`])
211	}
212	
213	function publishedPortArgv(port: WorkerPublishedPort): string[] {
214	  return ['-p', `${port.hostAddress}:${port.hostPort}:${port.containerPort}`]
215	}
216	
217	function deviceArgv(device: string): string[] {
218	  return ['--device', device]
219	}
220	
221	function mountArgv(mount: WorkerResourceMount): string[] {
222	  return ['-v', `${mount.source}:${mount.destination}:${mount.mode}`]
223	}
224	
225	/**
226	 * Traduce un perfil validado al argv de límites para `podman create`/`run`
227	 * — no ejecuta nada, sólo compone el argv (mismo contrato que
228	 * `thyrox_infrastructure_create_argv` en `src/lib/infrastructure.sh`: un
229	 * perfil inválido rehúsa antes de emitir ningún argumento).
230	 */
231	export function workerResourceLimitArgv(profile: WorkerResourceProfile): string[] {
232	  validateWorkerResourceProfile(profile)
233	  return [
234	    ...cpuLimitArgv(profile.cpus),
235	    ...memoryLimitArgv(profile.memoryMib),
236	    ...pidsLimitArgv(profile.pidsLimit),
237	    ...networkArgv(profile.network),
238	    ...rootfsArgv(profile.readOnlyRootfs),
239	    ...profile.mounts.flatMap(mountArgv),
240	    ...environmentArgv(profile.environment ?? {}),
241	    ...(profile.publishedPorts ?? []).flatMap(publishedPortArgv),
242	    ...(profile.devices ?? []).flatMap(deviceArgv),
243	  ]
244	}

