     8	 * CA. Sin proxy en ninguna fuente, la salida es directa.
     9	 *
    10	 * El valor viaja como `--env` y queda en `podman inspect`, así que una URL
    11	 * con usuario o contraseña se rehúsa en vez de propagarse.
    12	 */
    13	import type { WorkerNetworkMode, WorkerResourceMount } from '@thyrox/podman-execution/workerResourceProfile.ts'
    14	
    15	export const JOB_EGRESS_ENV = {
    16	  proxyUrl: 'THYROX_JOB_EGRESS_PROXY_URL',
    17	  caBundle: 'THYROX_JOB_EGRESS_CA_BUNDLE',
    18	} as const
    19	
    20	const INHERITED_PROXY_ENV = ['HTTPS_PROXY', 'https_proxy'] as const
    21	const INHERITED_CA_ENV = ['NODE_EXTRA_CA_CERTS', 'SSL_CERT_FILE'] as const
    22	
    23	export type JobEgress =
    24	  | { readonly kind: 'direct' }
    25	  | { readonly kind: 'proxy'; readonly proxyUrl: string; readonly caBundlePath?: string }
    26	
    27	export class JobEgressError extends Error {
    28	  constructor(reason: string) {
    29	    super(`salida de red del trabajo inválida: ${reason}`)
    30	    this.name = 'JobEgressError'
    31	  }
    32	}
    33	
    34	type Environment = Readonly<Record<string, string | undefined>>
    35	
    36	function firstDeclared(env: Environment, names: readonly string[]): string | undefined {
    37	  return names.map(name => env[name]?.trim()).find(value => !!value)
    38	}
    39	
    40	function requirePublicProxyUrl(value: string): string {
    41	  let url: URL
    42	  try {
    43	    url = new URL(value)
    44	  } catch {
    45	    throw new JobEgressError(`${value} no es una URL`)
    46	  }
    47	  if (url.protocol !== 'http:' && url.protocol !== 'https:') throw new JobEgressError(`${value} no es una URL http(s)`)
    48	  if (url.username || url.password) throw new JobEgressError('la URL del proxy lleva credencial y quedaría en podman inspect')
    49	  return value
    50	}
