    52	export function resolveJobEgress(env: Environment): JobEgress {
    53	  const proxyUrl = firstDeclared(env, [JOB_EGRESS_ENV.proxyUrl, ...INHERITED_PROXY_ENV])
    54	  if (!proxyUrl) return { kind: 'direct' }
    55	  const caBundlePath = firstDeclared(env, [JOB_EGRESS_ENV.caBundle, ...INHERITED_CA_ENV])
    56	  return { kind: 'proxy', proxyUrl: requirePublicProxyUrl(proxyUrl), ...(caBundlePath ? { caBundlePath } : {}) }
    57	}
