    72	 * se declaró, el CA montado de sólo lectura.
    73	 */
    74	export function jobNetworkProfile(egress: JobEgress): JobNetworkProfile {
    75	  if (egress.kind === 'direct') return { network: 'bridge', environment: {}, mounts: [] }
