     1	/**
     2	 * Probar que la copia remota de un artefacto es legible y exacta
     3	 * (TASK-THYROX-0728), separado de dónde corre la prueba.
     4	 *
     5	 * `verifyPublishedArtifact` es el método: resolver el tag por HEAD con un
     6	 * consumidor sin credencial, exigir que apunte al digest publicado, y
     7	 * materializar blob a blob verificando cada sha256 y borrando cada blob
     8	 * antes de bajar el siguiente. El disco que consume se mide, no se supone.
     9	 *
    10	 * Quién lo ejecuta es un `ArtifactVerifier`: en proceso para las suites, o
    11	 * como trabajo de la primitiva de Podman (`podmanJobVerifier.ts`) para que
    12	 * la prueba no comparta el almacenamiento ni las credenciales del
    13	 * publicador.
    14	 */
    15	import { rm } from 'node:fs/promises'
    16	
    17	import type { ArtifactLocation, ArtifactRegistry, ArtifactResult, MaterializedFile, PinnedArtifact } from './artifactRegistry.js'
    18	
    19	export interface Verification {
    20	  readonly resolvedDigest: string
    21	  readonly blobsVerified: readonly MaterializedFile[]
    22	  /** Disco consumido como máximo durante la verificación, medido. */
    23	  readonly measuredPeakBytes: number
    24	}
    25	
    26	/** El trabajo que verifica terminó sin dejar veredicto: ni el registry ni el artefacto respondieron mal. */
    27	export interface VerificationJobFailure {
    28	  readonly status: 'job_failed'
    29	  readonly exitCode: number
    30	  readonly detail: string
    31	}
    32	
    33	export type VerificationFailure = Exclude<ArtifactResult<unknown>, { status: 'success' }> | VerificationJobFailure
    34	
    35	export type VerificationOutcome =
    36	  | { readonly status: 'verified'; readonly verification: Verification }
    37	  | { readonly status: 'unverified'; readonly result: VerificationFailure }
    38	
    39	export interface ArtifactVerifier {
    40	  verify(pinned: PinnedArtifact, location: ArtifactLocation): Promise<VerificationOutcome>
    41	}
    42	
    43	export interface VerificationContext {
    44	  /** Consumidor anónimo: lo que prueba que el artefacto es legible sin credencial. */
    45	  readonly consumer: ArtifactRegistry
    46	  /** Directorio donde se materializa cada blob, uno a la vez; se borra al terminar. */
    47	  readonly verifyDir: string
    48	  /** Bytes libres del disco donde verifica; se muestrean para medir el pico real. */
    49	  readonly freeBytes: () => number
    50	}
    51	
    52	export async function verifyPublishedArtifact(
    53	  context: VerificationContext,
    54	  pinned: PinnedArtifact,
    55	  location: ArtifactLocation,
    56	): Promise<VerificationOutcome> {
    57	  try {
    58	    const resolved = await context.consumer.resolveArtifact(location)
    59	    if (resolved.status !== 'success') return { status: 'unverified', result: resolved }
    60	    if (resolved.value.digest !== pinned.digest) {
    61	      return { status: 'unverified', result: { status: 'integrity_error', detail: `el tag resuelve a ${resolved.value.digest}, no a ${pinned.digest}` } }
    62	    }
    63	    const startFree = context.freeBytes()
    64	    let lowestFree = startFree
    65	    const pulled = await context.consumer.pullArtifact(pinned, context.verifyDir, {
    66	      discardAfterVerify: true,
    67	      onVerified: () => { lowestFree = Math.min(lowestFree, context.freeBytes()) },
    68	    })
    69	    if (pulled.status !== 'success') return { status: 'unverified', result: pulled }
    70	    return {
    71	      status: 'verified',
    72	      verification: { resolvedDigest: resolved.value.digest, blobsVerified: pulled.value, measuredPeakBytes: startFree - lowestFree },
    73	    }
    74	  } finally {
    75	    await rm(context.verifyDir, { recursive: true, force: true })
    76	  }
    77	}
